using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace PID2Process;

internal static class InteractionSelfTest
{
    internal static void Run(string output,Action<bool,string> check)
    {
        foreach(var (vector,expected) in new[]{(new Vector(30,10),new Vector(30,0)),(new Vector(-30,10),new Vector(-30,0)),(new Vector(10,30),new Vector(0,30)),(new Vector(10,-30),new Vector(0,-30))}){var axis=0;check(OverlayTransforms.Direction(vector,true,ref axis)==expected,"SHIFT-Verschiebung: "+expected);}
        var locked=0;OverlayTransforms.Direction(new(10,2),true,ref locked);check(OverlayTransforms.Direction(new(12,40),true,ref locked)==new Vector(12,0),"SHIFT hält Achse über die gesamte Ziehbewegung");check(OverlayTransforms.Direction(new(12,40),false,ref locked)==new Vector(12,40)&&locked==0,"Ohne SHIFT freie Verschiebung");
        var item=new EquipmentItem{X=.2,Y=.2,Width=.2,Height=.1};OverlayTransforms.Resize(item,.3,.11,true,.2,.1);check(Math.Abs(item.Width/item.Height-2)<1e-10&&item.Width>.2&&item.Width<.3,"SHIFT-Skalierung hält ursprüngliches Seitenverhältnis");OverlayTransforms.Resize(item,2,2,true,.2,.1);check(Math.Abs(item.Width/item.Height-2)<1e-10&&Math.Abs(item.X+item.Width-1)<1e-10,"Proportionale Skalierung bleibt an Seitengrenze unverzerrt");OverlayTransforms.Resize(item,.12,.14,false,.2,.1);check(item.Width==.12&&item.Height==.14,"Ohne SHIFT getrennte Breite und Höhe");
        var project=new EngineeringProject();var original=new EquipmentItem{Tag="V-1",Type=EquipmentType.IsolationValve,Variant="3-Wege",X=.2,Y=.3,Width=.1,Height=.1,Actuator=ActuatorType.Piston,ShowStateText=true,GroupId=Guid.NewGuid()};project.Equipment.Add(original);var pipe=new PipeSegment{StartConnection=new(){EquipmentId=original.Id,Port="Left"},Points=[new(.2,.3),new(.5,.3)]};project.Pipes.Add(pipe);var scenario=new Scenario();scenario.EquipmentStates[original.Id]="A-C";scenario.TextValues[original.Id]="Text";scenario.TankStates[original.Id]=new(){Filled=true};project.Scenarios.Add(scenario);var step=new ControlStep{ScenarioId=scenario.Id};step.EquipmentStates[original.Id]="Geschlossen";step.TankStates[original.Id]=new(){Pressurized=true};project.ControlSteps.Add(step);
        var copy=OverlayTransforms.Copy(project,original);var second=OverlayTransforms.Copy(project,original);check(copy.Id!=original.Id&&second.Id!=copy.Id&&copy.Tag=="V-1-Kopie"&&second.Tag=="V-1-Kopie-2"&&copy.GroupId is null,"STRG-Kopie besitzt eigene ID, eindeutigen Tag und keine Gruppenzuordnung");
        check(copy.ShowStateText&&copy.Actuator==original.Actuator&&scenario.EquipmentStates[copy.Id]=="A-C"&&step.EquipmentStates[copy.Id]=="Geschlossen"&&scenario.TankStates[copy.Id].Filled==true&&!ReferenceEquals(scenario.TankStates[original.Id],scenario.TankStates[copy.Id]),"Kopie übernimmt Eigenschaften und unabhängige Szenario-/Schrittzuweisungen");OverlaySelection.Move(project,new HashSet<Guid>{copy.Id},.1,.1);check(original.X==.2&&original.Y==.3&&copy.X>.2&&pipe.StartConnection!.EquipmentId==original.Id,"Kopieren/Verschieben erhält Original und seine Rohranschlüsse");OverlaySelection.Delete(project,new HashSet<Guid>{copy.Id});check(!scenario.EquipmentStates.ContainsKey(copy.Id)&&!step.TankStates.ContainsKey(copy.Id)&&project.Equipment.Contains(original),"Abbruch einer Kopie bereinigt ausschließlich ihre eigenen Zuweisungen");
        var plain=new EquipmentItem{Type=EquipmentType.IsolationValve,Variant="2-Wege",Actuator=ActuatorType.Piston};var shape=(Grid)PageVisual.Symbol(plain,1400,1000,"Geschlossen");check(!shape.Children.OfType<Canvas>().Any()&&PageVisual.CaptionOffset(plain,1400)==0,"Ventil-Zustandstext standardmäßig vollständig ausgeblendet");plain.ShowStateText=true;shape=(Grid)PageVisual.Symbol(plain,1400,1000,"Geschlossen");var caption=shape.Children.OfType<Canvas>().Single().Children.OfType<TextBlock>().Single();check(caption.Text=="Geschlossen"&&caption.FontSize<=6&&caption.TextWrapping==TextWrapping.NoWrap,"Optionaler Zustandstext bleibt klein und einzeilig");
        var triples=new EquipmentItem{Type=EquipmentType.IsolationValve,Variant="3-Wege"};foreach(var (state,active) in new[]{("Offen",new[]{"Left","Right","Bottom"}),("Geschlossen",Array.Empty<string>()),("A-B",new[]{"Left","Right"}),("A-C",new[]{"Left","Bottom"}),("B-C",new[]{"Right","Bottom"})})check(SymbolCatalog.Get(triples).Shapes.Where(x=>x.Part is "Left" or "Right" or "Bottom").All(x=>SymbolCatalog.FillColor(triples,x,state)==(active.Contains(x.Part!)?"#00FF00":"#808080")),"Dreiwege-Flächenfarben: "+state);
        check(SymbolCatalog.Get(triples).Shapes.Where(x=>x.Part is not null).All(x=>SymbolCatalog.FillColor(triples,x,"Störung")=="#FF0000"),"Störung färbt alle Dreiwegeanschlüsse rot");
        foreach(var type in new[]{EquipmentType.PumpMotor,EquipmentType.Compressor,EquipmentType.Fan}){var x=new EquipmentItem{Type=type,Variant="Pumpe"};var fill=SymbolCatalog.Get(x).Shapes.First(s=>s.Part is not null);check(SymbolCatalog.FillColor(x,fill,"Ein")=="#00FF00"&&SymbolCatalog.FillColor(x,fill,"Aus")=="#808080"&&SymbolCatalog.FillColor(x,fill,"Störung")=="#FF0000","EIN/AUS/Störung-Farben: "+type);}
        var json=JsonSerializer.Serialize(plain,ProjectServices.JsonOptions);check(JsonSerializer.Deserialize<EquipmentItem>(json,ProjectServices.JsonOptions)!.ShowStateText&& !JsonSerializer.Deserialize<EquipmentItem>("{}",ProjectServices.JsonOptions)!.ShowStateText,"Zustandstext-Option persistent, im Altformat standardmäßig aus");
        var owner=new MainWindow();check(owner.Title.Contains(BuildInfo.Version)&&Version.TryParse(BuildInfo.Version,out _),"Buildversion im Fenster und Assembly");var buttons=Find(owner).OfType<Button>();check(!buttons.Any(x=>x.Tag?.ToString()=="ControlValve|Regelventil"),"Regelventil aus Bibliothek entfernt");
        var atlas=new EngineeringProject();var colors=new Scenario();atlas.Scenarios.Add(colors);
        for(var i=0;i<3;i++){var x=new EquipmentItem{Type=EquipmentType.IsolationValve,Variant="2-Wege",Tag=new[]{"Geschlossen","Offen","Störung"}[i],Actuator=ActuatorType.Piston,X=.04,Y=.04+i*.28,Width=.20,Height=.20/ .85,Opacity=1};atlas.Equipment.Add(x);colors.EquipmentStates[x.Id]=x.Tag;}
        var states=new[]{"A-B","A-C","Offen","Geschlossen","B-C","Störung"};for(var i=0;i<states.Length;i++){var x=new EquipmentItem{Type=EquipmentType.IsolationValve,Variant="3-Wege",Tag=states[i],Actuator=ActuatorType.Manual,X=.35+(i%2)*.32,Y=.04+(i/2)*.28,Width=.20,Height=.20/.85,Opacity=1};atlas.Equipment.Add(x);colors.EquipmentStates[x.Id]=states[i];}
        var white=BitmapSource.Create(1,1,96,96,PixelFormats.Bgra32,null,new byte[]{255,255,255,255},4);var image=PageVisual.Render(atlas,1,1400,.85,colors,white);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var file=File.Create(Path.Combine(output,"valve-colors.png")))png.Save(file);File.WriteAllText(Path.Combine(output,"valve-colors.pid2process.json"),JsonSerializer.Serialize(atlas,ProjectServices.JsonOptions));
    }
    private static IEnumerable<DependencyObject> Find(DependencyObject node){yield return node;for(var i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)foreach(var child in Find(VisualTreeHelper.GetChild(node,i)))yield return child;}
}
